// Renders every generated file in memory: per sub-brand (brand/dist/<name>/…) and, for a full
// build, the guidelines site's bundle. Returns { [repo-relative path]: contents }.
import fs from 'node:fs';
import path from 'node:path';
import { config, prefixesFor, resolveSelected, brandDir } from './tokens.mjs';
import { renderCss, renderSiteCss } from './format-css.mjs';
import { renderSwift } from './format-swift.mjs';
import { renderData } from './format-data.mjs';
import { renderFigma } from './format-figma.mjs';
import { renderSheet } from './format-sheet.mjs';
import { printModel, renderPrintCsv, renderPrintHtml, renderPrintJson } from './format-print.mjs';
import { contrastSummary, evaluateContrast, loadPairSpec } from './contrast.mjs';
import { evaluateRoles } from './roles.mjs';

/** Check results for one resolved sub-brand (also embedded in its outputs). */
export function evaluate(resolved) {
  const contrast = evaluateContrast(resolved, loadPairSpec(brandDir, resolved.sb), config.coreRamps);
  const roles = evaluateRoles(resolved.sb);
  return { contrast, roles };
}

const wants = (sb, output) => sb.isCore || sb.manifest.platforms.some((p) => config.platformOutputs[p]?.includes(output));

export async function renderAll(only) {
  const all = await resolveSelected(only);
  const files = {};
  const index = [];
  for (const resolved of all) {
    const { sb } = resolved;
    const prefixes = prefixesFor(sb);
    const results = evaluate(resolved);
    const summary = {
      contrast: contrastSummary(results.contrast),
      roles: { checked: results.roles.checked, chromeHues: results.roles.chromeHues, scopedHues: results.roles.scopedHues, budget: results.roles.budget, problems: results.roles.problems.length },
    };
    const dir = `${config.outputs.dist}/${sb.name}`;
    files[`${dir}/tokens.json`] = renderData(resolved, config, prefixes, summary);
    files[`${dir}/sheet.md`] = renderSheet(resolved, config, prefixes, summary);
    if (sb.manifest.figmaVariables === true) files[`${dir}/figma-variables.json`] = renderFigma(resolved, config);
    if (wants(sb, 'css')) files[`${dir}/tokens.css`] = renderCss(resolved, config, prefixes.css);
    if (wants(sb, 'swift')) files[`${dir}/Tokens.swift`] = renderSwift(resolved, config, prefixes.swift);
    if (wants(sb, 'print')) {
      const model = printModel(resolved, config);
      files[`${dir}/print/swatches.json`] = renderPrintJson(model);
      files[`${dir}/print/swatches.csv`] = renderPrintCsv(model);
      files[`${dir}/print/swatches.html`] = renderPrintHtml(model);
    }
    // For the site's index: the manifest plus a few resolved colours to paint cards with.
    const byKey = new Map(resolved.tokens.map((t) => [t.key, t]));
    const colourOf = (key) => {
      const t = byKey.get(key);
      return t ? (t.modeDependent ? t.raw : { dark: t.raw.dark, light: t.raw.dark }) : null;
    };
    index.push({
      name: sb.name,
      manifest: sb.manifest,
      prefix: prefixes,
      outputs: Object.keys(files).filter((f) => f.startsWith(`${dir}/`)).map((f) => f.slice(dir.length + 1)),
      summary,
      swatches: {
        base: colourOf('color.surface.base'),
        raised: colourOf('color.surface.raised'),
        text: colourOf('color.text.primary'),
        secondary: colourOf('color.text.secondary'),
        accent: colourOf('color.accent.fill'),
        border: colourOf('color.border.subtle'),
      },
      proportion: [sb.manifest.proportion, ...(sb.manifest.proportion.alternates ?? [])].map((system) => ({
        name: system.name,
        parts: system.parts.map((p) => ({ ...p, hex: [p.color].flat().map((k) => byKey.get(k)?.raw.dark) })),
      })),
    });
  }
  // The guidelines site is optional in a project (brand:sync --no-site, or deleted): render it only if present.
  if (!only && fs.existsSync(path.join(brandDir, 'site'))) {
    files[config.outputs.siteCss] = renderSiteCss(all, config, config.defaultPrefix.css);
    files[config.outputs.siteIndex] =
      JSON.stringify({ generated: 'GENERATED by brand/scripts/build.mjs — do not edit. Regenerate: npm run brand:build', subbrands: index }, null, 2) + '\n';
  }
  return files;
}
